"""Brand assets, inlined.

The hypercube mark lives here as base64 so every report stays a **single
self-contained file** (ADR-015) — a ``data:`` URI is not an external fetch, so
the no-external-assets contract holds. Both sizes come from
``build/machine_scanner.ico``, the same master the Windows binary embeds, so the
tab icon, the file icon and the page header are the same mark.
"""

from __future__ import annotations

# 32x32 — browser tab icon.
FAVICON_B64 = ""

# 72x72 — the mark shown in a report header. Designed on black, so place it on a
# dark band rather than a light card.
MARK_B64 = ""

FAVICON_LINK = (
    f"<link rel='icon' type='image/png' href='data:image/png;base64,{FAVICON_B64}'>"
)

MARK_IMG = (
    "<img alt='' width='36' height='36' "
    f"src='data:image/png;base64,{MARK_B64}'>"
)
